/** Current page language: "ka", "en" or "ru" (set on <html lang> by the build). */
export const lang = STRINGS[document.documentElement.lang] ? document.documentElement.lang : 'ka';

/** UI strings for the current language. */
export const t = STRINGS[lang];

/** Relative path from the current page to the site root ("" or "../"). */
export const root = document.documentElement.dataset.root || '';

/** Product name in the current language. */
export const productName = (p) => (lang === 'en' ? p.name.en : lang === 'ru' ? p.name.ru : p.name.ka);

/** "Shelf life: 210 days" from catalog values such as "210 Days" / "1 Year" / "6 month". */
export function shelfLife(value) {
  const m = value && value.match(/(\d+)\s*(Days|Year|month)/);
  if (!m) return '';
  const unit = { Days: 'days', Year: 'year', month: 'month' }[m[2]];
  return `${t.shelf.label}: ${m[1]} ${t.shelf[unit]}`;
}
